/* From Uiverse.io by coding-masala - Tags: radio */
.__UIV_SCOPE__ .radio-buttons {
  display: flex;
  flex-direction: column;
  color: white;
}

.__UIV_SCOPE__ .radio-button {
  display: flex;
  align-items: center;
  margin-bottom: 10px;
  cursor: pointer;
}

.__UIV_SCOPE__ .radio-button input[type="radio"] {
  display: none;
}

.__UIV_SCOPE__ .radio-circle {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid #aaa;
  position: relative;
  margin-right: 10px;
}

.__UIV_SCOPE__ .radio-circle::before {
  content: "";
  display: block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: #ddd;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0);
  transition: all 0.2s ease-in-out;
}

.__UIV_SCOPE__ .radio-button input[type="radio"]:checked + .radio-circle::before {
  transform: translate(-50%, -50%) scale(1);
}

.__UIV_SCOPE__ .radio-button:nth-of-type(1) input[type="radio"]:checked + .radio-circle::before {
  background-color: #ff6600;
}

.__UIV_SCOPE__ .radio-button:nth-of-type(2) input[type="radio"]:checked + .radio-circle::before {
  background-color: #ffffff;
}

.__UIV_SCOPE__ .radio-button:nth-of-type(3) input[type="radio"]:checked + .radio-circle::before {
  background-color: #26be00;
}

.__UIV_SCOPE__ .radio-label {
  font-size: 16px;
  font-weight: bold;
}

.__UIV_SCOPE__ .radio-button:hover .radio-circle {
  border-color: #555;
}

.__UIV_SCOPE__ .radio-button:hover input[type="radio"]:checked + .radio-circle::before {
  background-color: #555;
}
